import os
from typing import Optional

class Config:
    # NotchPay Configuration
    NOTCHPAY_API_KEY: str = os.environ.get("NOTCHPAY_API_KEY", "sandbox_notchpay_api_key")
    NOTCHPAY_API_SECRET: str = os.environ.get("NOTCHPAY_API_SECRET", "sandbox_notchpay_api_secret")
    NOTCHPAY_BASE_URL: str = os.environ.get("NOTCHPAY_BASE_URL", "https://sandbox.notchpay.com/api")

    # PesaPal Configuration
    PESAPAL_CONSUMER_KEY: str = os.environ.get("PESAPAL_CONSUMER_KEY", "sandbox_pesapal_consumer_key")
    PESAPAL_CONSUMER_SECRET: str = os.environ.get("PESAPAL_CONSUMER_SECRET", "sandbox_pesapal_consumer_secret")
    PESAPAL_BASE_URL: str = os.environ.get("PESAPAL_BASE_URL", "https://demo.pesapal.com/v3/api")

    # General Configuration
    API_HOST: str = os.environ.get("API_HOST", "0.0.0.0")
    API_PORT: int = int(os.environ.get("API_PORT", "8000"))
    DEBUG: bool = os.environ.get("DEBUG", "False").lower() == "true"
    SECRET_KEY: str = os.environ.get("SECRET_KEY", "your-secret-key-here")

    @property
    def notchpay_credentials(self) -> dict:
        return {
            "api_key": self.NOTCHPAY_API_KEY,
            "api_secret": self.NOTCHPAY_API_SECRET,
        }

    @property
    def pesapal_credentials(self) -> dict:
        return {
            "consumer_key": self.PESAPAL_CONSUMER_KEY,
            "consumer_secret": self.PESAPAL_CONSUMER_SECRET,
        }

config = Config()

from fastapi import FastAPI, HTTPException, Depends, Request
from fastapi.testclient import TestClient
from typing import List, Dict, Any
import os
from datetime import datetime

from config import config
from models import PaymentRequest, WebhookPayload, PaymentStatus
from schemas import PaymentInitiateRequest, PaymentInitiateResponse, GatewayList, HealthCheck
from security import verify_webhook_signature
from gateways.base import PaymentGateway
from gateways.notchpay import NotchPayGateway
from gateways.pesapal import PesaPalGateway

app = FastAPI(title="Mobile Money Hub")

# In-memory storage for payments
payments_db: Dict[str, Dict[str, Any]] = {}

# Gateway factory
def get_gateway(operator: str) -> PaymentGateway:
    """Factory function to get the appropriate payment gateway based on operator."""
    if operator.lower() == "mtn":
        return NotchPayGateway(config.notchpay_credentials)
    elif operator.lower() == "airtel":
        return PesaPalGateway(config.pesapal_credentials)
    else:
        raise HTTPException(status_code=400, detail=f"Unsupported operator: {operator}")

@app.get("/health", response_model=HealthCheck)
async def health_check():
    """Health check endpoint."""
    return HealthCheck()

@app.get("/gateways", response_model=GatewayList)
async def list_gateways():
    """List available payment gateways."""
    return GatewayList(gateways=["notchpay", "pesapal"])

@app.post("/payments/initiate", response_model=PaymentInitiateResponse)
async def initiate_payment(payment_request: PaymentRequest):
    """Initiate a payment through the appropriate gateway."""
    try:
        gateway = get_gateway(payment_request.operator)
        payment_data = {
            "amount": payment_request.amount,
            "currency": payment_request.currency,
            "reference_id": payment_request.reference_id,
            "customer_name": payment_request.customer_name,
            "customer_phone": payment_request.customer_phone,
            "customer_email": payment_request.customer_email,
            "metadata": payment_request.metadata
        }

        # In sandbox mode, we'll simulate a deterministic response
        payment_id = f"PAYMENT_{payment_request.reference_id}"
        gateway_name = gateway.__class__.__name__.lower().replace("gateway", "")

        # Store payment details
        payments_db[payment_id] = {
            "reference_id": payment_request.reference_id,
            "operator": payment_request.operator,
            "amount": payment_request.amount,
            "currency": payment_request.currency,
            "status": "PENDING",
            "gateway": gateway_name,
            "created_at": datetime.utcnow().isoformat()
        }

        return PaymentInitiateResponse(
            payment_id=payment_id,
            gateway=gateway_name,
            status="pending"
        )
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))

@app.post("/webhooks/{gateway}")
async def handle_webhook(gateway: str, payload: WebhookPayload, request: Request):
    """Handle webhook notifications from payment gateways."""
    try:
        # Verify the webhook signature
        is_valid = verify_webhook_signature(payload, gateway, await request.body())
        if not is_valid:
            raise HTTPException(status_code=401, detail="Invalid webhook signature")

        # Update payment status in our database
        payment_id = None
        for pid, p_data in payments_db.items():
            if p_data["reference_id"] == payload.reference_id:
                payment_id = pid
                break

        if payment_id:
            payments_db[payment_id].update({
                "status": payload.status.value,
                "gateway": payload.gateway,
                "transaction_id": payload.transaction_id,
                "updated_at": datetime.utcnow().isoformat()
            })
            return {"status": "success", "message": "Webhook processed"}
        else:
            raise HTTPException(status_code=404, detail="Payment not found")
    except Exception as e:
        raise HTTPException(status_code=400, detail=str(e))

if __name__ == "__main__":
    import uvicorn
    uvicorn.run(app, host=config.API_HOST, port=config.API_PORT)

import pytest
from fastapi.testclient import TestClient
from main import app

@pytest.fixture
def client():
    """Create a test client."""
    return TestClient(app)

def test_health_check(client):
    """Test the health check endpoint."""
    response = client.get("/health")
    assert response.status_code == 200
    assert response.json() == {"status": "healthy"}

def test_list_gateways(client):
    """Test the gateways listing endpoint."""
    response = client.get("/gateways")
    assert response.status_code == 200
    assert response.json() == {"gateways": ["notchpay", "pesapal"]}

def test_initiate_payment_mtn(client):
    """Test payment initiation with MTN operator (NotchPay)."""
    payment_data = {
        "amount": 1000,
        "currency": "XOF",
        "reference_id": "REF123456",
        "customer_name": "John Doe",
        "customer_phone": "22312345678",
        "customer_email": "john@example.com",
        "metadata": {"order_id": "ORD123"}
    }
    response = client.post("/payments/initiate", json=payment_data)
    assert response.status_code == 200
    data = response.json()
    assert data["gateway"] == "notchpay"
    assert data["status"] == "pending"
    assert data["payment_id"].startswith("PAYMENT_REF123456")

def test_initiate_payment_airtel(client):
    """Test payment initiation with Airtel operator (PesaPal)."""
    payment_data = {
        "amount": 2000,
        "currency": "XOF",
        "reference_id": "REF789012",
        "customer_name": "Jane Smith",
        "customer_phone": "22387654321",
        "customer_email": "jane@example.com",
        "metadata": {"order_id": "ORD456"}
    }
    response = client.post("/payments/initiate", json=payment_data)
    assert response.status_code == 200
    data = response.json()
    assert data["gateway"] == "pesapal"
    assert data["status"] == "pending"
    assert data["payment_id"].startswith("PAYMENT_REF789012")

def test_invalid_webhook_signature(client):
    """Test webhook endpoint with invalid signature."""
    # This test simulates a webhook with an invalid signature
    # In a real implementation, you would need to mock the webhook payload and signature
    webhook_data = {"status": "completed", "payment_id": "PAYMENT_REF123456"}
    headers = {"X-Webhook-Signature": "invalid_signature"}

    response = client.post("/webhooks/notchpay", json=webhook_data, headers=headers)
    assert response.status_code == 401  # or 400 depending on implementation

def test_valid_webhook_signature(client):
    """Test webhook endpoint with valid signature."""
    # This test simulates a webhook with a valid signature
    # In a real implementation, you would need to mock the webhook payload and signature
    webhook_data = {"status": "completed", "payment_id": "PAYMENT_REF123456"}
    headers = {"X-Webhook-Signature": "valid_signature"}  # This would be a proper HMAC signature in reality

    response = client.post("/webhooks/pesapal", json=webhook_data, headers=headers)
    assert response.status_code == 200
    assert response.json() == {"status": "received"}
